CREATE TABLE IF NOT EXISTS "content_about_page" ("id" TEXT PRIMARY KEY, "_status" TEXT NOT NULL DEFAULT 'draft', "_published_at" TEXT, "_first_published_at" TEXT, "_published_snapshot" TEXT, "_created_at" TEXT NOT NULL, "_updated_at" TEXT NOT NULL, "_created_by" TEXT, "_updated_by" TEXT, "_published_by" TEXT, "_scheduled_publish_at" TEXT, "_scheduled_unpublish_at" TEXT, "title" TEXT, "meta_description" TEXT, "bio" TEXT);
INSERT INTO "content_about_page" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","meta_description","bio") VALUES('c9gdiv7ca3','published','2026-03-21T18:14:09.781Z','2026-03-21T18:14:09.781Z','{"title":"About","meta_description":"A local foodie in Reykjavík writing the guides she wishes existed.","bio":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"I''m a wife and mum of two, living in the Hlíðar neighbourhood of Reykjavík. I spend an unreasonable amount of time thinking about where to eat next."}]},{"type":"paragraph","children":[{"type":"span","value":"I started "},{"type":"link","url":"https://instagram.com/rvkfoodie","children":[{"type":"span","value":"@rvkfoodie"}]},{"type":"span","value":" because the restaurant advice out there for visitors was terrible — TripAdvisor top-tens full of tourist traps, bloggers who''d never set foot in a real neighbourhood spot, and Google results that rewarded mediocrity."}]},{"type":"paragraph","children":[{"type":"span","value":"These guides are my antidote. Every restaurant, café, and bar in them is a place I go to myself, often with my family. I know the chefs, I know the menus, and I know what to order. Nothing is sponsored. Nothing is paid placement. If it''s in the guide, it''s because I genuinely think you should eat there."}]},{"type":"paragraph","children":[{"type":"span","value":"The guides are updated regularly — places close, menus change, new spots open. When you buy a guide, you''re getting recommendations that are current, not a snapshot from two years ago."}]},{"type":"paragraph","children":[{"type":"span","value":"Questions? Suggestions? Reach me at "},{"type":"link","url":"mailto:rvkfoodie@rvkfoodie.is","children":[{"type":"span","value":"rvkfoodie@rvkfoodie.is"}]},{"type":"span","value":" or DM on Instagram."}]}]}}}','2026-03-21T18:14:09.781Z','2026-03-21T18:14:09.781Z','admin','admin','admin',NULL,NULL,'About','A local foodie in Reykjavík writing the guides she wishes existed.','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"I''m a wife and mum of two, living in the Hlíðar neighbourhood of Reykjavík. I spend an unreasonable amount of time thinking about where to eat next."}]},{"type":"paragraph","children":[{"type":"span","value":"I started "},{"type":"link","url":"https://instagram.com/rvkfoodie","children":[{"type":"span","value":"@rvkfoodie"}]},{"type":"span","value":" because the restaurant advice out there for visitors was terrible — TripAdvisor top-tens full of tourist traps, bloggers who''d never set foot in a real neighbourhood spot, and Google results that rewarded mediocrity."}]},{"type":"paragraph","children":[{"type":"span","value":"These guides are my antidote. Every restaurant, café, and bar in them is a place I go to myself, often with my family. I know the chefs, I know the menus, and I know what to order. Nothing is sponsored. Nothing is paid placement. If it''s in the guide, it''s because I genuinely think you should eat there."}]},{"type":"paragraph","children":[{"type":"span","value":"The guides are updated regularly — places close, menus change, new spots open. When you buy a guide, you''re getting recommendations that are current, not a snapshot from two years ago."}]},{"type":"paragraph","children":[{"type":"span","value":"Questions? Suggestions? Reach me at "},{"type":"link","url":"mailto:rvkfoodie@rvkfoodie.is","children":[{"type":"span","value":"rvkfoodie@rvkfoodie.is"}]},{"type":"span","value":" or DM on Instagram."}]}]}}');
